const express = require('express');
const app = express();
require('dotenv').config(); // Load environment variables

// Use environment variables for configuration
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const LOG_LEVEL = process.env.LOG_LEVEL || 'info';

// Security middleware
const helmet = require('helmet');
app.use(helmet({
  contentSecurityPolicy: NODE_ENV === 'production' ? undefined : false,
}));

// CORS configuration
const cors = require('cors');
const allowedOrigins = process.env.ALLOWED_ORIGINS 
  ? process.env.ALLOWED_ORIGINS.split(',') 
  : ['http://localhost:3000'];
app.use(cors({ origin: allowedOrigins }));

// Rate limiting
const rateLimit = require('express-rate-limit');
const rateLimitWindowMs = parseInt(process.env.RATE_LIMIT_WINDOW_MS) || 15 * 60 * 1000; // 15 minutes
const rateLimitMax = parseInt(process.env.RATE_LIMIT_MAX) || 100;

const limiter = rateLimit({
  windowMs: rateLimitWindowMs,
  max: rateLimitMax,
  message: process.env.RATE_LIMIT_MESSAGE || 'Too many requests from this IP',
});
app.use(limiter);

// Body parser limits
app.use(express.json({ limit: process.env.BODY_LIMIT || '10mb' }));

// Request logging
if (process.env.REQUEST_LOGGING !== 'false') {
  app.use((req, res, next) => {
    if (LOG_LEVEL === 'debug') {
      console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
    }
    next();
  });
}

// Health endpoint
app.get('/health', (req, res) => {
  const healthStatus = process.env.HEALTH_STATUS || 'ok';
  res.json({ 
    status: healthStatus, 
    timestamp: new Date().toISOString(),
    environment: NODE_ENV
  });
});

// Users endpoint (should have authentication in production)
app.get('/users', (req, res) => {
  // In production, this should fetch from a database
  // Mock data for example purposes - in real app, use proper auth
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];
  res.json(users);
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err);
  const statusCode = err.statusCode || 500;
  const message = NODE_ENV === 'production' 
    ? 'Internal Server Error' 
    : err.message;
  res.status(statusCode).json({ 
    error: process.env.ERROR_MESSAGE || message 
  });
});

// Start server
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
  });
}

module.exports = app;

